-- Pixel Kampung save fixture: schema v22.
-- Fake data only: a tiny seeded test town (fake brains, made-up memories), never a real save.
-- Frozen: never edit. Made by `npm run save-fixture`; see docs/design/upgrades.md.
CREATE TABLE events (
          seq INTEGER PRIMARY KEY,
          t INTEGER NOT NULL,
          type TEXT NOT NULL,
          data TEXT NOT NULL
        );
CREATE TABLE ledger (
          seq INTEGER PRIMARY KEY,
          t INTEGER NOT NULL,
          from_id TEXT NOT NULL,
          to_id TEXT NOT NULL,
          cents INTEGER NOT NULL,
          reason TEXT NOT NULL
        );
CREATE TABLE memories (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        resident TEXT NOT NULL,
        t INTEGER NOT NULL,
        kind TEXT NOT NULL,
        text TEXT NOT NULL,
        importance INTEGER NOT NULL
      );
CREATE TABLE meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE snapshot (
          id INTEGER PRIMARY KEY CHECK (id = 1),
          t INTEGER NOT NULL,
          world TEXT NOT NULL,
          brains TEXT NOT NULL
        );
CREATE INDEX memories_by_resident ON memories (resident, t);
